  : annotated.filter((a) => a.lifecycle === 'open' || a.lifecycle === 'controlled_test');

if (isProd && open.length === 0) {
  const resolved = annotated.filter((a) => a.lifecycle === 'resolved' || a.lifecycle === 'controlled_test');
  const last = resolved.length ? resolved[resolved.length - 1] : annotated[annotated.length - 1];
  const lines = [
    'Активных рабочих ошибок нет.',
    '',
    'Последняя устранённая ошибка:',
    `${last.code} · ${last.stageRu} · ${last.when}`,
    last.msg,
  ];
  return [{ json: { ...lead, reply_text: lines.join('\n'), error_lifecycle: 'resolved' } }];
}

const last = open[open.length - 1];
const title = (!isProd && last.lifecycle === 'controlled_test')
  ? 'Последняя тестовая ошибка'
  : (isProd ? 'Последняя рабочая ошибка' : 'Последняя ошибка');

const lines = [
  title,
  '',
  'Статус: ' + (last.lifecycle === 'controlled_test' ? 'controlled_test' : 'open'),
  'Время: ' + last.when,
  'Этап: ' + last.stageRu,
  'Код: ' + last.code,
];
if (!isProd && last.lifecycle === 'controlled_test') {
  lines.push('Тип: контролируемая синтетическая проверка');
}
lines.push('Сообщение: ' + last.msg);

return [{ json: { ...lead, reply_text: lines.join('\n'), error_lifecycle: last.lifecycle, open_error_count: openProd.length } }];

// Phase 3D.5 — ADMIN "Config Summary"
// Phase 3D.5 inlined access-lib for n8n Code nodes
/**
 * Phase 3D.5 — public access + ACCESS_CONTROL registry authorization.
 * Pure module for harness + n8n Code sync. No raw Telegram IDs in fixtures.
 */

const ACCESS_HEADERS = [
  'telegram_user_id',
  'telegram_user_hash',
  'telegram_username',
  'display_name',
  'role',
  'status',
  'first_seen_at',
  'last_seen_at',
  'requested_at',
  'approved_at',
  'approved_by',
  'revoked_at',
  'revoked_by',
  'source',
  'notes',
];

const ACCESS_EVENT_HEADERS = [
  'ts',
  'opaque_user_ref',
  'event',
  'prior_role',
  'prior_status',
  'new_role',
  'new_status',
  'actor_ref',
  'source',
  'outcome',
  'detail',
];

const ADMIN_ONLY_COMMANDS = new Set([
  '/config',
  '/health',
  '/status',
  '/stats',
  '/last_error',
  '/ai_on',
  '/ai_off',
  '/ai_status',
  '/leads',
  '/test_lead',
