function denyReply({ auth_role, deny_reason }) {
  if (deny_reason === 'blocked' || auth_role === 'blocked') {
    return 'Доступ к боту ограничен.';
  }
  if (deny_reason === 'admin_only' && auth_role === 'moderator') {
