  if (String(r.manager_status || '').trim()) s += 1;
  if (String(r.telegram_message_ref || '').trim()) s += 1;
  return s;
}

function prefer(a, b) {
  const ta = parseTs(a);
  const tb = parseTs(b);
  if (tb !== ta) return tb > ta ? b : a;
  return fieldScore(b) > fieldScore(a) ? b : a;
}

