function isControlledSynthetic(row) {
  const blob = JSON.stringify(row).toLowerCase();
  return /synthetic|fixture|phase_3b|controlled/.test(blob)
    || /SYNTHETIC/i.test(String(row.lead_id || ''))
    || String(row.source_marker || '').toUpperCase() === 'SYNTHETIC_TEST';
}

function classifyLifecycle(row) {
  const explicit = String(row.error_lifecycle || row.lifecycle || row.error_status || row.status || '').toLowerCase();
  if (['resolved', 'closed', 'done', 'fixed'].includes(explicit)) return 'resolved';
  if (['controlled_test', 'synthetic', 'test'].includes(explicit)) return 'controlled_test';
  if (isControlledSynthetic(row)) return 'controlled_test';

  const code = String(row.error_code || '').toLowerCase();
  const t = Date.parse(rowTs(row));
  // Phase 3C.2 Telegram flood / retry incident — closed in Phase 3D (retain history, not active)
  if (/telegram_retry_exhausted|telegram_delivery_failed|telegram_flood|retry_flood/.test(code)) {
    if (!Number.isNaN(t) && t < Date.parse('2026-07-31T16:30:00.000Z')) return 'resolved';
