}

function summarize(row) {
  const stageKey = String(row.stage || 'unknown');
  const stageRu = STAGE_RU[stageKey] || stageKey;
  const code = row.error_code || '—';
  let msg = String(row.message || row.error_message || '').slice(0, 300);
  if (code === 'telegram_delivery_failed' && !msg) msg = 'Не удалось доставить карточку в Telegram.';
  if (code === 'telegram_delivery_failed' && /unknown|error|fail/i.test(msg) && msg.length < 40) {
