/**
 * Resolve effective role from ACCESS_CONTROL with CONFIG bootstrap fallback.
 * Source of truth: ACCESS_CONTROL when a row exists.
 * CONFIG admin_user_ids = emergency/bootstrap Admin.
 * CONFIG manager_action_user_ids = migration fallback only when no ACCESS_CONTROL row.
 */
function resolveIdentity({ user_id, access_rows, admin_user_ids, manager_action_user_ids }) {
  const uid = String(user_id || '');
  const row = findAccessRow(access_rows, uid);
  const admins = parseIds(admin_user_ids);
  const managers = parseIds(manager_action_user_ids);
  const configAdmin = admins.includes(uid);
  const configManager = managers.includes(uid);

  if (row) {
    if (row.status === 'blocked' || row.role === 'blocked') {
      return { role: 'blocked', status: 'blocked', row, registry_source: 'ACCESS_CONTROL' };
    }
    if (row.role === 'admin' && row.status === 'active') {
      return { role: 'admin', status: 'active', row, registry_source: 'ACCESS_CONTROL' };
    }
    if (row.role === 'moderator' && row.status === 'active') {
      return { role: 'moderator', status: 'active', row, registry_source: 'ACCESS_CONTROL' };
    }
    if (row.status === 'revoked') {
      return { role: 'public', status: 'revoked', row, registry_source: 'ACCESS_CONTROL' };
    }
    // pending / public
    return {
      role: row.role === 'public' || !row.role ? 'public' : row.role,
      status: row.status || 'pending',
      row,
      registry_source: 'ACCESS_CONTROL',
    };
  }

  // No row — CONFIG bootstrap / migration fallback
  if (configAdmin) {
    return { role: 'admin', status: 'active', row: null, registry_source: 'CONFIG_FALLBACK' };
  }
  if (configManager) {
    return { role: 'moderator', status: 'active', row: null, registry_source: 'CONFIG_FALLBACK' };
  }
  return { role: 'public', status: 'none', row: null, registry_source: 'none' };
}

function authorizeUser({
  user_id,
  command,
  access_rows,
  admin_user_ids,
  manager_action_user_ids,
}) {
  const cmd = String(command || '').trim().toLowerCase();
  const identity = resolveIdentity({ user_id, access_rows, admin_user_ids, manager_action_user_ids });
  const { role, status } = identity;
  const actionCapable = (role === 'admin' || role === 'moderator') && status === 'active';

  if (role === 'blocked' || status === 'blocked') {
    return {
      authorized: false,
      auth_role: 'blocked',
      manager_action_authorized: false,
      deny_reason: 'blocked',
      identity,
    };
  }

  if (cmd === '/__callback') {
    if (actionCapable) {
      return {
        authorized: true,
        auth_role: role,
        manager_action_authorized: true,
        deny_reason: null,
        identity,
      };
    }
    return {
      authorized: false,
      auth_role: role === 'public' || status === 'pending' || status === 'revoked' ? role : 'public',
      manager_action_authorized: false,
      deny_reason: 'callback_denied',
      identity,
    };
  }

  if (PUBLIC_COMMANDS.has(cmd)) {
    return {
      authorized: true,
      auth_role: role === 'admin' ? 'admin' : (role === 'moderator' && status === 'active' ? 'moderator' : 'public'),
      manager_action_authorized: actionCapable,
      deny_reason: null,
      identity,
    };
  }

  if (ADMIN_ONLY_COMMANDS.has(cmd)) {
    if (role === 'admin' && status === 'active') {
      return {
        authorized: true,
        auth_role: 'admin',
        manager_action_authorized: true,
        deny_reason: null,
        identity,
      };
    }
    if (role === 'moderator' && status === 'active') {
      return {
        authorized: false,
        auth_role: 'moderator',
        manager_action_authorized: true,
        deny_reason: 'admin_only',
        identity,
      };
    }
    return {
      authorized: false,
      auth_role: 'public',
      manager_action_authorized: false,
      deny_reason: 'staff_only',
      identity,
    };
  }

  // Unknown command — allow through to dispatcher (non-blocked)
  return {
    authorized: true,
    auth_role: role === 'admin' && status === 'active' ? 'admin'
      : (role === 'moderator' && status === 'active' ? 'moderator' : 'public'),
    manager_action_authorized: actionCapable,
    deny_reason: null,
    identity,
    unknown_command: true,
  };
}

