  }
  if (row.status === 'revoked') {
    return {
      ok: true,
      idempotent: true,
      reply: 'Права модератора отозваны.',
      row,
      notify_text: null,
      event: null,
    };
  }
  const updated = {
    ...row,
    role: 'moderator',
    status: 'revoked',
    revoked_at: nowIso,
    revoked_by: actor_ref,
    last_seen_at: nowIso,
  };
  return {
    ok: true,
    idempotent: false,
    reply: 'Права модератора отозваны.',
    row: updated,
    notify_chat_id: updated.telegram_user_id,
