    adminCount: parseIds(admin_user_ids).length,
    moderatorCount: Math.max(0, parseIds(manager_action_user_ids).length - parseIds(admin_user_ids).filter((id) => parseIds(manager_action_user_ids).includes(id)).length),
    actionCapable: new Set([...parseIds(admin_user_ids), ...parseIds(manager_action_user_ids)]).size,
    source: 'CONFIG_FALLBACK',
  };
}


