const ACCESS_HEADERS = [
  'telegram_user_id',
  'telegram_user_hash',
  'telegram_username',
  'display_name',
  'role',
  'status',
  'first_seen_at',
  'last_seen_at',
  'requested_at',
  'approved_at',
  'approved_by',
  'revoked_at',
  'revoked_by',
  'source',
  'notes',
];

const ACCESS_EVENT_HEADERS = [
  'ts',
  'opaque_user_ref',
  'event',
  'prior_role',
  'prior_status',
  'new_role',
  'new_status',
  'actor_ref',
  'source',
  'outcome',
  'detail',
];

const ADMIN_ONLY_COMMANDS = new Set([
  '/config',
  '/health',
  '/status',
  '/stats',
  '/last_error',
  '/ai_on',
  '/ai_off',
  '/ai_status',
  '/leads',
  '/test_lead',
