// Token algorithm SYNC with OPS-Format_Telegram_Lead_Card.v3d3.js / formatter-lib.mjs

function computeActionToken(leadId) {
  const s = String(leadId || '');
  try {
    const crypto = require('crypto');
    return crypto.createHash('sha256').update(s).digest('hex').slice(0, 12);
  } catch (e) {
    let h1 = 0x811c9dc5 >>> 0;
    for (let i = 0; i < s.length; i++) {
      h1 ^= s.charCodeAt(i);
      h1 = Math.imul(h1, 0x01000193);
    }
    let h2 = 0x9e3779b9 >>> 0;
    for (let i = 0; i < s.length; i++) {
      h2 ^= s.charCodeAt(i);
      h2 = Math.imul(h2, 0x85ebca6b);
      h2 = (h2 << 13) | (h2 >>> 19);
    }
    return ((h1 >>> 0).toString(16).padStart(8, '0') + (h2 >>> 0).toString(16).padStart(8, '0')).slice(0, 12);
  }
}

function actorHash(userId) {
  return 'u:' + computeActionToken('actor:' + String(userId || ''));
}

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function fmtMoscow(v) {
  const d = v ? new Date(v) : new Date();
  if (Number.isNaN(d.getTime())) return '—';
  const parts = new Intl.DateTimeFormat('ru-RU', {
    timeZone: 'Europe/Moscow',
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit', hour12: false,
  }).formatToParts(d);
  const get = (t) => parts.find((p) => p.type === t)?.value || '';
  return get('day') + '.' + get('month') + '.' + get('year') + ' ' + get('hour') + ':' + get('minute') + ' МСК';
}

function codeField(label, value) {
  const v = String(value ?? '').trim();
  if (!v) return '';
  const lower = v.toLowerCase();
  if (['unknown', '44', '#error!', '#value!', '#ref!', '#n/a', 'n/a', 'na', '-', '—', 'null', 'undefined'].includes(lower)) {
    return '';
  }
  if (/#error!|#value!|#ref!|#n\/a|formula\s*parse\s*error|^#\w+!/i.test(v)) return '';
  return label + '\n<code>' + esc(v) + '</code>\n';
}

