    event_type: 'manager_action_duplicate_ignored',
    answer_text: '⚠️ Статус лида уже изменён. Обновление не выполнено.',
    detail: JSON.stringify({ prior, desired, outcome: 'conflict', actor, source: 'telegram_callback', workflow_version: 'Admin.dev' }),
  } }];
}

const when = fmtMoscow(nowIso);
let editText = (desired === 'processed' ? '✅ Обработан' : '🚫 Спам') + '\n\n';
editText += codeField('Клиент', lead.client_name);
editText += codeField('Телефон', lead.phone);
editText += codeField('Email', lead.email);
if (lead.messenger) editText += codeField('Telegram', lead.messenger);
editText += codeField('Сайт', lead.site);
editText += 'Услуга: ' + esc(lead.service || '—') + '\n';
if (lead.summary) editText += '\nЗапрос\n' + esc(String(lead.summary).slice(0, 500)) + '\n';
editText += '\n' + (desired === 'processed' ? '✅ Обработан' : '🚫 Спам') + '\nВремя: ' + when + '\n';

return [{ json: {
  ...outBase,
  callback_outcome: 'applied',
  sheets_mutate: true,
  telegram_edit: true,
  lead_id: String(lead.lead_id),
  source_message_id: String(lead.source_message_id || ''),
  prior_status: prior,
  new_status: desired,
  manager_status: desired,
  manager_status_updated_at: nowIso,
  manager_status_updated_by: actor,
  manager_status_source: 'telegram_callback',
  last_manager_action: desired === 'processed' ? 'marked_processed' : 'marked_spam',
  last_manager_action_at: nowIso,
  closed_at: nowIso,
  close_reason: desired === 'processed' ? 'processed' : 'spam',
  assigned_to: actor,
  spam_at: desired === 'spam' ? nowIso : (lead.spam_at || ''),
  spam_by: desired === 'spam' ? actor : (lead.spam_by || ''),
  spam_reason: desired === 'spam' ? 'manager_callback' : (lead.spam_reason || ''),
  manager_action_processed_at: desired === 'processed' ? nowIso : (lead.manager_action_processed_at || ''),
  manager_action_processed_by: desired === 'processed' ? actor : (lead.manager_action_processed_by || ''),
  telegram_message_ref: String(auth.callback_message_id || lead.telegram_message_ref || ''),
  telegram_chat_ref_hash: actorHash(auth.callback_chat_id || auth.chat_id),
  telegram_action_token: token,
  event_type: desired === 'processed' ? 'manager_marked_processed' : 'manager_marked_spam',
  answer_text: desired === 'processed'
    ? '✅ Лид отмечен как обработанный.'
    : 'Лид отмечен как спам.',
  edit_text: editText,
  detail: JSON.stringify({
    prior, new_status: desired, outcome: 'applied', actor,
    source: 'telegram_callback', workflow_version: 'Admin.dev',
  }),
} }];

// Phase 3D.3.1 — ADMIN "Recent Leads" (/leads 3|5|10). n8n Code node body (runOnceForAllItems).
// Fixes: exact arg parse; newest-first unique business leads; ordinals 1..N; invalid contact
// suppression; lifecycle status; copy-friendly archive cards; no action buttons.
// events_to_append (lead_card_recovered) once per command on the first card item.

const j = $('Check User Authorization').first().json;
const rowsRaw = $('Read CLEAN for Leads').all().map((i) => i.json).filter((r) => r && typeof r === 'object');

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function dash(s) {
  const v = String(s ?? '').trim();
  return v ? esc(v) : '—';
}

const INVALID_EXACT = new Set([
  'unknown', '44', '#error!', '#value!', '#ref!', '#n/a', 'n/a', 'na', '-', '—', 'null', 'undefined',
]);

function isValidContactValue(value) {
  const v = String(value ?? '').trim();
  if (!v) return false;
  const lower = v.toLowerCase();
  if (INVALID_EXACT.has(lower)) return false;
  if (/#error!|#value!|#ref!|#n\/a/i.test(v)) return false;
  if (/formula\s*parse\s*error/i.test(v)) return false;
  if (/^#\w+!/i.test(v)) return false;
  return true;
}

function contactBlock(label, value, markCorrupt) {
  const raw = String(value ?? '').trim();
  if (!raw) return [];
  if (isValidContactValue(raw)) return [label, '<code>' + esc(raw) + '</code>', ''];
  if (markCorrupt && /#error!|#value!|#ref!|#n\/a|formula\s*parse\s*error/i.test(raw)) {
    return ['⚠️ Контакт в архивной записи повреждён', ''];
  }
  return [];
}

function messengerLabel(value) {
  const v = String(value ?? '');
  return (/^@/.test(v) || /t\.me/i.test(v)) ? '💬 Telegram:' : '💬 Мессенджер:';
}

// Exact canonical integers only: 3|5|10. Default 5. Reject 03, 7, trailing garbage.
const args = Array.isArray(j.args) ? j.args.map((a) => String(a).trim()).filter(Boolean) : [];
let limit = 5;
let invalid = false;
if (args.length === 0) {
  limit = 5;
} else if (args.length !== 1 || !/^(3|5|10)$/.test(args[0])) {
  invalid = true;
} else {
  limit = Number(args[0]);
}

const INVALID_REPLY = '⚠️ Укажите количество: 3, 5 или 10.\nНапример: /leads 5';

if (invalid) {
  return [{ json: {
    ...j,
    leads_recovery_outcome: 'invalid_arg',
    reply_text: INVALID_REPLY,
    events_to_append: [],
  } }];
}

function isSynthetic(r) {
  const marker = String(r.phase_marker || '');
  return Boolean(
    r.__synthetic === true
    || r.synthetic_fixture === true
    || r.fixture_id
    || String(r.marker || '') === 'SYNTHETIC_TEST'
    || /SYNTHETIC_TEST/i.test(String(r.client_name || ''))
    || /PHASE_3[A-Z0-9.]*/i.test(marker)
    || /synthetic/i.test(String(r.lead_id || ''))
    || /synthetic/i.test(String(r.source || '')),
  );
}

function isTechnicalRetryOnly(r) {
  const t = String(r.row_kind || r.record_kind || r.entry_type || '').toLowerCase();
  if (t === 'technical_retry' || t === 'retry_only' || t === 'tech_retry') return true;
  if (r.technical_retry === true || r.is_technical_retry === true) return true;
  return false;
}

function businessKey(r) {
  const leadId = String(r.lead_id || '').trim();
  if (leadId) return 'lead:' + leadId;
  const gmail = String(r.source_message_id || r.gmail_message_id || r.message_id || '').trim();
  if (gmail) return 'gmail:' + gmail;
  const created = String(r.created_at || r.processed_at || r.updated_at || '').trim();
  const site = String(r.site || '').trim();
  const name = String(r.client_name || '').trim();
  const fb = [name, site, created].filter(Boolean).join('|');
  return fb ? 'fb:' + fb : '';
}

function parseTs(r) {
  const candidates = [
    r.lead_received_at, r.received_at, r.created_at, r.processed_at, r.updated_at, r.manager_status_updated_at,
  ];
  for (const c of candidates) {
    if (!c) continue;
    const d = new Date(c);
    if (!Number.isNaN(d.getTime())) return d.getTime();
  }
  const rn = Number(r.row_number);
  return Number.isFinite(rn) ? rn : 0;
}

function fieldScore(r) {
  let s = 0;
  for (const k of ['client_name', 'phone', 'email', 'messenger', 'site', 'summary', 'first_reply_text']) {
    const v = String(r[k] ?? '').trim();
    if (v && isValidContactValue(v)) s += 2;
  }
  if (String(r.manager_status || '').trim()) s += 1;
  if (String(r.telegram_message_ref || '').trim()) s += 1;
  return s;
}

function prefer(a, b) {
  const ta = parseTs(a);
  const tb = parseTs(b);
  if (tb !== ta) return tb > ta ? b : a;
  return fieldScore(b) > fieldScore(a) ? b : a;
}

const MAX_SCAN = 250;
const filtered = rowsRaw.filter((r) => !isSynthetic(r) && !isTechnicalRetryOnly(r));
const bounded = [...filtered].sort((a, b) => parseTs(b) - parseTs(a)).slice(0, MAX_SCAN);

const bestByKey = new Map();
for (const r of bounded) {
  const key = businessKey(r);
  if (!key) continue;
  if (!bestByKey.has(key)) bestByKey.set(key, r);
  else bestByKey.set(key, prefer(bestByKey.get(key), r));
}

const unique = [...bestByKey.values()].sort((a, b) => parseTs(b) - parseTs(a));
const picked = unique.slice(0, limit);
const total = picked.length;
const availableUnique = unique.length;

if (total === 0) {
  return [{ json: {
    ...j,
    leads_recovery_outcome: 'empty',
    reply_text: '📁 Архив пуст: подходящих карточек не найдено.',
    requested_count: limit,
    returned_count: 0,
    available_unique: 0,
    events_to_append: [{
      event_type: 'lead_card_recovered',
      detail: 'requested=' + limit + ';returned=0;source=admin_command;outcome=empty',
      at: new Date().toISOString(),
    }],
  } }];
}

const dupMap = {
  new: '🟢 Новый лид',
  repeat: '🟡 Повторный лид',
  possible: '🟠 Возможный повтор',
  reprocessed: '🔵 Повторная обработка',
};
const lifeMap = {
  pending: '🕓 Ожидает обработки',
  processed: '✅ Обработан',
  spam: '🚫 Спам',
};
const svcMap = { Audit: 'Аудит', SEO: 'SEO', Direct: 'Директ', Site: 'Сайт', Other: 'Другое' };

function normalizeLife(r) {
  const raw = String(r.manager_status || '').trim().toLowerCase();
  return (raw === 'processed' || raw === 'spam') ? raw : 'pending';
}

function buildCard(r, idx, totalCount) {
  const header = dupMap[r.duplicate_status] || '⚪ Лид';
  const life = lifeMap[normalizeLife(r)];
  const lines = [];
  lines.push('📁 Архивная карточка ' + (idx + 1) + ' из ' + totalCount);
  lines.push(header);
  lines.push(life);
  lines.push('');

  const nameBlocks = contactBlock('👤 Клиент:', r.client_name, false);
  lines.push(...nameBlocks);

  const phoneBlocks = contactBlock('📞 Телефон:', r.phone, true);
  const emailBlocks = contactBlock('✉️ Email:', r.email, true);
  const msgBlocks = String(r.messenger ?? '').trim()
    ? contactBlock(messengerLabel(r.messenger), r.messenger, true)
    : [];
  const siteBlocks = contactBlock('🌐 Сайт:', r.site, false);
  lines.push(...phoneBlocks, ...emailBlocks, ...msgBlocks, ...siteBlocks);

  lines.push('🛠 Услуга: ' + (svcMap[r.service] || dash(r.service)));
  lines.push('📝 Запрос: ' + dash(r.summary));
  lines.push('');

  const reply = String(r.first_reply_text || '').trim();
  if (reply && isValidContactValue(reply)) {
    lines.push('✉️ Ответ клиенту — нажмите на блок, чтобы скопировать:');
    lines.push('<pre>' + esc(reply) + '</pre>');
    lines.push('');
  }

  lines.push('ℹ️ Архивная копия. Статус меняется только в исходной карточке.');
  return lines.join('\n');
}

const recoveryEvent = [{
  event_type: 'lead_card_recovered',
  detail: 'requested=' + limit + ';returned=' + total + ';available=' + availableUnique + ';source=admin_command;outcome=ok',
  at: new Date().toISOString(),
}];

const cards = picked.map((r, idx) => ({
  json: {
    reply_text: buildCard(r, idx, total),
    chat_id: j.chat_id,
    message_format_version: 'sm-msg-v2',
    leads_recovery_outcome: 'card',
    archive_card_index: idx + 1,
    archive_card_total: total,
    requested_count: limit,
    returned_count: total,
    available_unique: availableUnique,
    lead_id: r.lead_id || '',
    manager_status: normalizeLife(r),
    telegram_has_buttons: false,
    telegram_reply_markup: null,
    events_to_append: idx === 0 ? recoveryEvent : [],
  },
}));

if (total < limit) {
  cards.push({
    json: {
      reply_text: '📁 Доступно уникальных лидов: ' + availableUnique + ' (запрошено /leads ' + limit + '). Показано: ' + total + '.',
      chat_id: j.chat_id,
      message_format_version: 'sm-msg-v2',
      leads_recovery_outcome: 'notice',
      archive_notice: true,
      requested_count: limit,
      returned_count: total,
      available_unique: availableUnique,
      events_to_append: [],
    },
  });
} else {
  cards.push({
    json: {
      reply_text: '📁 Показано архивных карточек: ' + total + ' (лимит /leads ' + limit + ').',
      chat_id: j.chat_id,
      message_format_version: 'sm-msg-v2',
      leads_recovery_outcome: 'notice',
      archive_notice: true,
      requested_count: limit,
      returned_count: total,
      available_unique: availableUnique,
      events_to_append: [],
    },
  });
}

return cards;

const h = $('Handle Callback Action').first().json;
const j = $input.first().json || {};
return [{ json: {
  ...h,
  ...j,
  answer_callback: true,
  callback_query_id: String(h.callback_query_id || ''),
  answer_text: String(h.answer_text || 'OK'),
  reply_text: String(h.answer_text || 'OK'),
  chat_id: String(h.chat_id || h.edit_chat_id || ''),
}}];

const h = $('Handle Callback Action').first().json;
const j = $input.first().json || {};
const failed = Boolean(j.error || j.message?.error_code || j.ok === false);
if (!failed) return [{ json: { ...h, edit_ok: true, reply_text: h.answer_text, chat_id: h.chat_id } }];
return [{ json: {
  ...h,
  edit_ok: false,
  reply_text: 'Статус сохранён, но сообщение в Telegram обновить не удалось.',
  chat_id: h.chat_id,
  event_type_extra: 'telegram_edit_failed',
}}];
